ri = lambda : int(input())
rl = lambda : list(map(int, input().split()))
rs = lambda : input()
from heapq import heappush, heappop

def solve():
	(n, m) = rl()
	z = []
	for i in range(n + 1):
		z.append([])
	visited = [0] * (n + 1)
	for _ in range(m):
		(x, y) = rl()
		z[y].append(x)
		visited[x] = 1
	prev = 0
	for i in range(1, n + 1):
		if prev + len(z[i]) > i:
			return [-1]
		prev += len(z[i])
	for i in range(1, n + 1):
		if not visited[i]:
			z[-1].append(i)
	ans = [0] * (n + 1)
	heap = []
	for i in range(n, 0, -1):
		while z[i]:
			heappush(heap, -z[i].pop())
		ans[i] = -heappop(heap)
	return ans[1:]

def main():
	for _ in range(ri()):
		print(*solve())
main()
